-- the string and table libraries, and the interpreter's own behaviour on
-- strings: patterns, gsub, sorting, concat, arg, varargs
local function show(...) print(select("#", ...), ...) end
show(arg[0], arg[1], arg[2], arg[3], #arg, arg[-1] ~= nil, ...)
show(("hello world"):find("o w"), ("hello"):find("l+"), ("hello"):find("xyz"), ("a.b"):find(".", 1, true), ("abc"):find("", 10), ("abc"):find("", 4))
show(("hello world from lua"):match("(%w+) (%w+)"), ("key=value"):match("^(%w+)=(%w*)$"), ("  trim  "):match("^%s*(.-)%s*$"), ("2024-01-15"):match("(%d+)-(%d+)-(%d+)"))
show(("hello"):gsub("l", "L"), ("hello"):gsub("l", "L", 1), ("hello world"):gsub("%w+", "<%0>"), ("abc"):gsub("", "-"), ("abc"):gsub(".", { a = 1, b = false }), ("abc"):gsub("%w", function(c) if c == "b" then return nil end return c:upper() end))
show(("x = 1, y = 2"):gsub("(%w+) = (%w+)", "%2 = %1"), ("$name is $age"):gsub("%$(%w+)", { name = "Lua", age = 30 }), ("abc"):gsub("b", "%%"), ("hello"):gsub("(l)(l)", "%2%1"))
for w in ("one two  three"):gmatch("%a+") do io.write("[", w, "]") end print()
for k, v in ("a=1, b=2, c=3"):gmatch("(%w+)=(%w+)") do io.write(k, "->", v, " ") end print()
for p in ("abc"):gmatch("()") do io.write(p, " ") end print()
show(("%bxy"):len(), ("f(a(b)c)d"):match("%b()"), ("[[x]]"):match("%[(%b[])%]"), ("THE (quick) fox"):find("%((%a+)%)"), ("hello"):match("%f[%a]%a+%f[%A]"), ("THE (quick) fox"):gsub("%f[%a]%u+%f[%A]", "X"))
show(("abc"):byte(), ("abc"):byte(-1), ("abc"):byte(1, -1), string.char(), string.char(104, 105), ("abc"):rep(3, "-"), ("abc"):rep(0), ("abc"):rep(1, "x"))
show(("Hello"):upper(), ("Hello"):lower(), ("abc"):reverse(), ("abc"):sub(2), ("abc"):sub(-2), ("abc"):sub(2, 1), ("abc"):sub(0), ("abc"):sub(-100, 100), #("abc"):sub(4))
show(("a,b,,c"):gsub(",", ";"), ("abc"):len(), #"\0\0\0", ("a\0b"):find("\0"), ("a\0b"):upper(), ("x"):rep(3) == "xxx")
show(tostring(1):len(), ("10"):rep(2) + 1, "5" * "2", "3" .. 4, 10 .. "", pcall(function() return "a" < 1 end), "a" < "b", "Z" < "a", "" < "a", "a" < "aa", "\xff" > "a")
show(table.concat({ 1, 2, 3 }, ", "), table.concat({}, "x"), table.concat({ "a", "b", "c" }, "", 2), table.concat({ 1.5, 2, "x" }), pcall(table.concat, { 1, 2 }, ",", 1, 3))
local t = { 5, 2, 8, 1, 9, 3, 7, 4, 6, 10 }
table.sort(t) show(table.concat(t, " "))
table.sort(t, function(a, b) return a > b end) show(table.concat(t, " "))
local words = { "banana", "Apple", "cherry", "apple", "Banana", "", "a" }
table.sort(words) show(table.concat(words, "|"))
table.sort(words, function(a, b) return a:lower() < b:lower() end) show(words[1], words[#words])
show(table.unpack({ 1, 2, 3 }), table.unpack({ 1, 2, 3 }, 2), table.unpack({ 1, 2, 3 }, 2, 5), select("#", table.unpack({}, 1, 3)))
show(table.pack(1, nil, 3).n, table.pack().n, #table.pack(1, 2))
t = { 1, 2, 3 } table.insert(t, 4) table.insert(t, 1, 0) show(table.concat(t, ","), table.remove(t), table.remove(t, 1), table.concat(t, ","), table.remove({}), table.remove(t, #t + 1))
show(table.move({ 1, 2, 3 }, 1, 3, 2)[3], table.concat(table.move({ 1, 2, 3 }, 1, 3, 3, {}), ",", 3, 5), pcall(table.move, {}, 1, math.maxinteger, 2))
show(#{ 1, 2, 3, nil }, #{ n = 1 }, #"", rawlen({ 1, 2 }), rawlen("abc"), rawequal("a", "a"), rawequal({}, {}))
show(next({}), next({ 10 }), type(next), select("#", next({ a = 1 })))
local keys = {} for k in pairs({ 10, 20, 30, x = 1 }) do keys[#keys + 1] = tostring(k) end table.sort(keys) show(table.concat(keys, " "))
show(string.format("%-10s|%10s|", "left", "right"), ("x"):rep(3, ", "), ("CamelCaseString"):gsub("(%u)", " %1"), ("  a  b  "):gsub("%s+", " "))
show(("hello"):find("l", -2), ("hello"):find("l", 10), ("hello"):find("", 6), ("hello"):find("", 7), ("héllo"):len(), ("héllo"):upper())
show(("%d%%"):format(50), ("%5.1f|%-5d|%05.1f"):format(3.14159, 42, 3.14159), ("%s %s"):format(nil, true), pcall(string.format, "%s"))
show(tostring(nil), tostring(true), tostring(123), tostring(1.0), tostring(-0.0), tostring(1e100), tostring("s"), type(tostring(print)):sub(1, 1))
show(load("return 'a' .. 'b' .. 'c'")(), load("return 1 .. 2")(), load("return -2 ^ 2")(), load("return 2 ^ -1")(), load("return 2 ^ 3 ^ 2")(), load("return not nil == true")(), load("return 1 .. 2 == '12'")())
show(("%s"):rep(3, "%"), ("a"):rep(5):find("aa", 1, true), ("aaa"):gsub("a", "b", 2), ("abc"):gsub("%w", "%0%0"), ("abc"):gsub("(a)(b)(c)", "%3%2%1"))
show(("x"):format(), pcall(string.format, "%d"), ("%c%c%c"):format(76, 117, 97), ("%q"):format("\r\n\t"), ("%q"):format(("\127"):rep(2) .. "\200"))
show(("one;two;;four"):gsub(";", "\n"), ("path/to/file.txt"):match("([^/]+)$"), ("path/to/file.txt"):match("^(.*)/"), ("file.tar.gz"):match("^(.-)%.(.*)$"))
show(#string.rep("ab", 1000, ","), string.rep("", 1e6), ("x"):rep(2^20):len())
